package model;
/** Faixa de aprovação comercial e seus limites. */
public class AlcadaComercial { private String nome; private double limiteDesconto; public String getNome(){return nome;} public void setNome(String v){nome=v;} public double getLimiteDesconto(){return limiteDesconto;} public void setLimiteDesconto(double v){limiteDesconto=v;} }